import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from scipy.spatial.distance import pdist, squareform
lines = open('answer.xyz').read().split('\n')[2:]
els=[]; xyz=[]
for l in lines:
    if l.strip():
        p=l.split(); els.append(p[0]); xyz.append([float(v) for v in p[1:4]])
xyz=np.array(xyz); D=squareform(pdist(xyz))
cov = {'H':0.31,'C':0.76,'O':0.66,'P':1.07,'Ni':1.24}
bonds=[(i,j) for i in range(len(els)) for j in range(i+1,len(els)) if D[i,j]<cov[els[i]]+cov[els[j]]+0.45]
col={'H':'0.6','C':'k','O':'r','P':'orange','Ni':'g'}
fig,axes=plt.subplots(1,3,figsize=(24,8))
views=[(0,1,'xy (drawing plane)'),(0,2,'xz'),(1,2,'yz')]
for ax,(i,j,t) in zip(axes,views):
    for a,b in bonds:
        ax.plot([xyz[a,i],xyz[b,i]],[xyz[a,j],xyz[b,j]],'-',lw=1,c='0.7')
    for k,e in enumerate(els):
        ax.scatter(xyz[k,i],xyz[k,j], s=120 if e not in ('H',) else 20, c=col[e], edgecolors='none', zorder=3)
    for k,e in enumerate(els):
        if e in ('Ni','P','O'): ax.annotate(e,(xyz[k,i],xyz[k,j]),color=col[e],fontsize=10,xytext=(xyz[k,i]+0.1,xyz[k,j]+0.1))
    ax.set_aspect('equal'); ax.axis('off'); ax.set_title(t)
plt.tight_layout(); plt.savefig('render.png',dpi=80)
print('bonds',len(bonds))
